{
  "findings": [
    {
      "check_id": "CKV_AWS_355",
      "title": "IAM policy allows wildcard resource for SSM StartSession",
      "resource": "aws_iam_policy.privesc-ssmStartSession-policy",
      "severity": "MEDIUM",
      "explanation": "The policy grants 'ssm:StartSession' and related actions on Resource = "*", allowing the principal to start sessions on any EC2 instance in the account, which is a privilege escalation risk."
    },
    {
      "check_id": "CKV_AWS_290",
      "title": "IAM policy allows write access without constraints",
      "resource": "aws_iam_policy.privesc-ssmStartSession-policy",
      "severity": "MEDIUM",
      "explanation": "'ssm:StartSession' is considered a write/action capability that can lead to remote code execution or data exfiltration. Granting it on all resources (*) violates least privilege principles."
    }
  ],
  "patched_code": "resource "aws_iam_policy" "privesc-ssmStartSession-policy" {
  name        = "privesc-ssmStartSession-policy"
  path        = "/"
  description = "Allows privesc via targeted ssm"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action = [
          "ec2:DescribeInstances",
          "ssm:StartSession",
           "ssm:DescribeSessions",
            "ssm:GetConnectionStatus",
            "ssm:DescribeInstanceProperties",
            "ssm:TerminateSession",
            "ssm:ResumeSession"
        ]
        Resource = "arn:aws:ssm:*:*:document/AWS-StartPortForwardingSessionToRemoteHost"
      },
    ]
  })
}",
  "fix_summary": "Replaced the wildcard Resource '*' with a specific ARN pattern for SSM documents to restrict where sessions can be started, mitigating the privilege escalation risk associated with unrestricted SSM StartSession permissions."
}
